  return doc({ title: 'Catálogo e oferta · Given in Grace', current: 'catalogo', screen: { code: '07', title: 'Catálogo e oferta' }, body, next: { t: 'Fechar fornecedor e conferir a amostra', b: 'Ver plano', h: 'plano-de-acao.html' } });
